<?php
session_start(); require __DIR__.'/includes/db.php'; $error=''; $success=''; if($_SERVER['REQUEST_METHOD']==='POST'){ $name=trim($_POST['name']??''); $email=trim($_POST['email']??''); $password=$_POST['password']??''; if($name===''||!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($password)<6){$error='Enter a name, valid email and password of at least 6 characters.';}else{$st=mysqli_prepare($conn,"SELECT id FROM users WHERE email=?");mysqli_stmt_bind_param($st,'s',$email);mysqli_stmt_execute($st);if(mysqli_num_rows(mysqli_stmt_get_result($st))>0){$error='Email already registered.';}else{$hash=password_hash($password,PASSWORD_DEFAULT);$st=mysqli_prepare($conn,"INSERT INTO users(name,email,password) VALUES(?,?,?)");mysqli_stmt_bind_param($st,'sss',$name,$email,$hash);if(mysqli_stmt_execute($st)){$success='Registration successful. You can now login.';}else{$error='Registration failed.';}}}} ?>
